import re
import time

import requests

from collections import defaultdict

from taf.rfrl.csv4all.resources.node.uboot_downgrade.exceptions import UbootDowngradeError
from taf.rfrl.csv4all.resources.utilities.test_global_constants import FIRMWARE_DICT
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class CSV4ALLUboot:
    def __init__(self, ssh_manager=None, smod=None, bbmod=None):
        self.fw_status_to_rp = ''
        self.ssh_manager = ssh_manager
        self.perform_reset = False
        self.uboot_scripts_prepared = False
        self.uboot_scripts = ['prepare-firmware.sh', 'prepare-firmware-manager.sh', 'prepare-firmware-common.sh',
                              'prepare-firmware-core-manager.sh']
        self.firmware_core_manager = "/ffs/run/prepare-firmware-core-manager.sh"
        self.smod_list = [smod[module]['Module Type'] for module in smod] if smod else []
        self.bbmod_list = [bbmod[module]['Module Type'] for module in bbmod] if bbmod else []
        self.modules = set(self.smod_list + self.bbmod_list)

    def uboot_downgrade(self, verify: bool = False):
        try:
            self.upload_uboot_scripts_on_node()
            self.ssh_manager.execute_command("chmod +x /ffs/run/prepare-firmware*", timeout="30")
            self.ssh_manager.execute_command("rm /user/toor4nsn/.ssh/known_hosts", timeout="30")
            downgrade_status = self.execute_uboot_script(timeout="120")
            if verify:
                return downgrade_status
            test_logger(f"Downgrade status:\n{downgrade_status}", console=False)
            if "FW not downgraded" in downgrade_status:
                downgrade_result = self.execute_uboot_script(verify=False)
                test_logger(f"Firmware downgrade result:\n{downgrade_result}", console=False)
                if "downgrade/update failed on SoC" in downgrade_result:
                    raise
                elif "Performed update at least on one core" in downgrade_result:
                    test_logger("Performed firmware update at least on one core")
                    self.perform_reset = True
                else:
                    test_logger("Unexpected output from uboot, more info in log.html", "WARN")
            elif "FW downgraded successfully" in downgrade_status:
                test_logger("Firmware downgrade not needed")
                self.perform_reset = False
            elif "Error, prepare-firmware.sh failed on Soc" in downgrade_status:
                test_logger("Error, prepare-firmware.sh failed on Soc", "ERROR")
                raise
            else:
                test_logger("Unexpected status from uboot, more info in log.html", "WARN")
        except Exception as e:
            test_logger(e, "ERROR")
            raise UbootDowngradeError()

    def execute_uboot_script(self, verify: bool = True, timeout: str = "1200") -> str:
        attempts = 3
        output = ""
        for attempt in range(1, attempts + 1):
            output = self.ssh_manager.execute_command(f"{self.firmware_core_manager} {'-v' if verify else '-u'} "
                                                      f"-p {self.ssh_manager.node_ssh_password}", timeout=timeout)
            if "Error, prepare-firmware.sh failed on Soc" in output:
                time.sleep(60)
                continue
            break
        return output

    def upload_uboot_scripts_on_node(self):
        for script in self.uboot_scripts:
            self.ssh_manager.upload_file_to_bts(script, f"/ffs/run/{script}")

    def prepare_uboot_scripts(self):
        headers = {"PRIVATE-TOKEN": "glpat--makhBkHJq8oi_33fECd"}
        for script in self.uboot_scripts:
            url = f"https://gitlabe1.ext.net.nokia.com/api/v4/projects/70751/repository/files/{script}/raw?ref=master"
            response = requests.get(url, headers=headers, stream=True)

            if response.status_code == 200:
                with open(script, 'wb') as output:
                    for chunk in response.iter_content(chunk_size=8192):
                        output.write(chunk)
                self.uboot_scripts_prepared = True
            else:
                test_logger(f"Couldn't download {script}, Uboot downgrade can't be performed", "ERROR")
                self.uboot_scripts_prepared = False
                break
        if self.uboot_scripts_prepared:
            test_logger("Uboot scripts downloaded correctly")

    def verify_firmware_upgrade_change(self, node_alias: str = None):
        def get_operations_from_found_files(module_type: str, found_files: list):
            operation_list = []
            for file_reg, operation in FIRMWARE_DICT.items():
                file_split = file_reg.split('__')[1]
                if any(file_split in file for file in found_files if module_type in file_reg):
                    operation_list.append(operation.replace(f"{module} ", ""))
            return operation_list

        try:
            differences = self._get_firmware_differences()
            modules_with_firmware_downgrade = defaultdict()
            for module in self.modules:
                fw_list = [fw_file.split("__")[1] for fw_file in FIRMWARE_DICT.keys() if module in fw_file]
                found_fw_files = [firmware_file.rstrip() for firmware_file in differences
                                  if re.findall("|".join(fw_list), firmware_file, flags=re.MULTILINE)]
                if found_fw_files:
                    modules_with_firmware_downgrade[module] = get_operations_from_found_files(module, found_fw_files)
            if modules_with_firmware_downgrade:
                fw_statuses_to_rp = [f"{module} {operation}" for module in modules_with_firmware_downgrade
                                     for operation in modules_with_firmware_downgrade[module]]
                self.fw_status_to_rp = ', '.join(fw_statuses_to_rp)
                prefix = f"[{node_alias}] " if node_alias else ""
                test_logger(f"{prefix}Upgraded FW: {dict(modules_with_firmware_downgrade)}", hyperlink=True)
                return True
            return False
        except Exception as e:
            test_logger(e, "ERROR")
            return False

    def _get_firmware_differences(self) -> set:
        firmware_files = defaultdict()
        pattern = re.compile(r"T1\.bin|T2\.bin|\.bin")
        for partition in ["stb", "run"]:
            patition_files = self.ssh_manager.execute_command(f"cd /ffs/{partition}/swpool/LFS/boot/; ls -1 *.bin")
            firmware_files[partition] = {pattern.sub("", file_name).rstrip()
                                         for file_name in patition_files.split("\n")}
        differences = firmware_files["run"] - firmware_files["stb"]
        return differences
